//! The `build` facet — a node records whether it compiles, and where its artifact is.
//!
//! # What this is actually for
//!
//! Not speed. The gate's sweep already hash-caches the whole set (2.7s → 0.3s), so per-node caching
//! saves little. The value is that **the verdict lives ON THE NODE**: `bsc graph impl get <id>` answers
//! "does this compile?" without running anything, and the artifact reference is what makes a node
//! *runnable* rather than merely stored — the original ask behind this epic.
//!
//! ```jsonc
//! "build": {
//!   "hash":      "<sha256 of the materialized source + toolchain + flags>",
//!   "verdict":   "pass" | "fail",
//!   "targets":   { "native": { "verdict": "pass" },
//!                  "wasm32": { "verdict": "pass", "artifact": "<sha256>", "bytes": 12385 } },
//!   "at":        "2026-08-19T…Z",
//!   "toolchain": "rustc 1.8x.0 (… )"
//! }
//! ```
//!
//! # The hash covers everything that can change the answer
//!
//! Source alone is not enough: the same code compiles or does not depending on the compiler and the
//! flags. A hash that ignored those would report a stale verdict as current after a toolchain bump —
//! the exact shape of "green while covering less" this repo keeps paying for. The MATERIALIZED source
//! is hashed rather than the record's own `code`, because a node's closure is part of what compiles:
//! editing a composed sibling must invalidate its dependents.
//!
//! # Artifacts are a SIDECAR, never inline
//!
//! `algorithms.json` is 8.74 MB and the frontend imports it. A 12 KB wasm per node would add ~1 MB of
//! base64 to a file every reader parses. Artifacts are content-addressed under
//! `~/.base-studio-code/knowledge/artifacts/<sha256>.<ext>` and the node stores only the hash — the same
//! shape sccache uses, at node granularity. They are a CACHE: derived, reproducible, and absent in a
//! fresh clone by design, which is why a missing artifact re-derives rather than failing.

use serde_json::{json, Value};

// Pure leaf free-functions, each its own record (decompose-bsc-graph-fat-records).
pub use facet_hash::facet_hash;
pub use is_current::is_current;
pub use facet::facet;
pub use artifact_name::artifact_name;
pub use materializes::materializes;
pub(crate) use takes_materializer_as_a_build_dependency::takes_materializer_as_a_build_dependency;
pub use crate_of::crate_of;
pub use is_tier_a::is_tier_a;
pub use wasm_export_count::wasm_export_count;
pub(crate) use leb128::leb128;

/// The flag set the wasm measurement was taken with. Changing it changes the artifact, so it is part of
/// the hash — 12,385 bytes with these, 1.5 MB without them.
pub const WASM_FLAGS: &[&str] = &[
    "-C", "opt-level=z",
    "-C", "panic=abort",
    "-C", "lto=fat",
    "-C", "codegen-units=1",
    "-C", "strip=symbols",
];

/// One target's outcome. `artifact` is a content hash, never a path — the sidecar's location is the
/// reader's business, and a path baked into a committed store would be machine-specific.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TargetOutcome {
    pub name: &'static str,
    pub passed: bool,
    pub artifact: Option<String>,
    pub bytes: Option<u64>,
    /// Exported function count — present only for a target where "can it be called?" is a real question.
    pub exports: Option<u32>,
    pub detail: Option<String>,
}

impl TargetOutcome {
    pub fn pass(name: &'static str) -> Self {
        Self { name, passed: true, artifact: None, bytes: None, exports: None, detail: None }
    }
    pub fn fail(name: &'static str, detail: impl Into<String>) -> Self {
        Self { name, passed: false, artifact: None, bytes: None, exports: None, detail: Some(detail.into()) }
    }
    pub fn with_artifact(mut self, sha: impl Into<String>, bytes: u64) -> Self {
        self.artifact = Some(sha.into());
        self.bytes = Some(bytes);
        self
    }
    /// Record how many functions the artifact exports, and say so when the answer is none.
    pub fn with_exports(mut self, exports: u32) -> Self {
        self.exports = Some(exports);
        if exports == 0 {
            self.detail = Some(
                "compiled, but exports NOTHING — a node needs a `#[no_mangle] extern \"C\"` wrapper to \
                 be callable. The export contract is `one-implementation-drives-the-animation`."
                    .into(),
            );
        }
        self
    }
}

/// The line a crate adds to its manifest to have its source materialized from the graph — the route
/// taken by every crate that owns no build script of its own.
///
/// Mirrored in `scripts/graph-rust-compile.mjs`; the two must move together, and that script's header
/// says so. Different languages, so the constant cannot be shared — only kept honest.
pub const MATERIALIZE_MARKER: &str = "build = \"../graph-materialize/build.rs\"";

/// The OTHER route into the same materializer, and missing it is a silent under-report.
///
/// A package gets exactly ONE build script, so a crate that already has one cannot point `build =`
/// anywhere: it takes `graph-materialize` as a build-dependency and CALLS it from its own `build.rs`
/// (`the-two-build-rs-crates-adopt-the-materializer-alongside-their-own`). `crates/data` and
/// `crates/bsc-config` do exactly that, and neither carries [`MATERIALIZE_MARKER`].
///
/// This constant exists because keying only on the marker made [`is_tier_a`] answer **false** for 20
/// healthy records the moment those two migrated, and `graph-rust-compile` then swept them as
/// standalone nodes and reported 16 of them FAILED — the precise libel the Tier-A exclusion exists to
/// prevent, restored by a manifest line rather than by anything about the records.
pub const MATERIALIZE_DEP: &str = "graph-materialize = { path = \"../graph-materialize\" }";

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_hash_changes_with_source_toolchain_or_flags() {
        let base = facet_hash("fn a() {}", "rustc 1.80", WASM_FLAGS);
        assert_ne!(base, facet_hash("fn b() {}", "rustc 1.80", WASM_FLAGS), "source");
        assert_ne!(base, facet_hash("fn a() {}", "rustc 1.81", WASM_FLAGS), "toolchain");
        assert_ne!(base, facet_hash("fn a() {}", "rustc 1.80", &["-C", "opt-level=3"]), "flags");
        assert_eq!(base, facet_hash("fn a() {}", "rustc 1.80", WASM_FLAGS), "stable for equal inputs");
    }

    /// The separator matters: without it `("ab", "c")` and `("a", "bc")` would hash identically.
    #[test]
    fn field_boundaries_cannot_be_confused() {
        assert_ne!(facet_hash("ab", "c", &[]), facet_hash("a", "bc", &[]));
    }

    #[test]
    fn a_node_with_no_facet_is_never_current() {
        assert!(!is_current(&json!({ "id": "a.rs" }), "abc"));
    }

    #[test]
    fn currency_is_exactly_a_hash_match() {
        let node = json!({ "build": { "hash": "abc" } });
        assert!(is_current(&node, "abc"));
        assert!(!is_current(&node, "def"));
    }

    #[test]
    fn the_facet_carries_every_target_and_its_artifact() {
        let f = facet(
            "h",
            "rustc 1.80",
            "2026-08-19T00:00:00Z",
            &[TargetOutcome::pass("native"), TargetOutcome::pass("wasm32").with_artifact("deadbeef", 12_385)],
        );
        assert_eq!(f["verdict"], json!("pass"));
        assert_eq!(f["targets"]["native"]["verdict"], json!("pass"));
        assert_eq!(f["targets"]["wasm32"]["artifact"], json!("deadbeef"));
        assert_eq!(f["targets"]["wasm32"]["bytes"], json!(12_385));
        assert_eq!(f["hash"], json!("h"));
    }

    /// A partial pass is a FAIL. Summarizing it as a pass is how a green report comes to mean less than
    /// the reader assumes.
    #[test]
    fn one_failing_target_fails_the_whole_facet() {
        let f = facet(
            "h",
            "t",
            "now",
            &[TargetOutcome::pass("native"), TargetOutcome::fail("wasm32", "no wasm32 target installed")],
        );
        assert_eq!(f["verdict"], json!("fail"));
        assert_eq!(f["targets"]["wasm32"]["detail"], json!("no wasm32 target installed"));
    }

    #[test]
    fn an_artifact_is_named_by_its_content_hash() {
        assert_eq!(artifact_name("abc123", "wasm"), "abc123.wasm");
    }

    #[test]
    fn an_export_less_module_is_reported_as_such_rather_than_a_bare_pass() {
        let t = TargetOutcome::pass("wasm32").with_artifact("sha", 86).with_exports(0);
        assert!(t.passed, "it did compile");
        assert_eq!(t.exports, Some(0));
        assert!(t.detail.as_deref().unwrap().contains("exports NOTHING"), "{t:?}");
    }

    #[test]
    fn a_module_with_exports_carries_the_count_and_no_warning() {
        let t = TargetOutcome::pass("wasm32").with_artifact("sha", 12_385).with_exports(3);
        assert_eq!(t.exports, Some(3));
        assert!(t.detail.is_none());
    }

    #[test]
    fn non_wasm_bytes_are_not_mistaken_for_a_module() {
        assert_eq!(wasm_export_count(b"not wasm at all"), None);
        assert_eq!(wasm_export_count(&[]), None);
    }

    /// The minimal real module: header only. No export section means nothing is exported.
    #[test]
    fn a_header_only_module_exports_nothing() {
        let m = [0x00, b'a', b's', b'm', 0x01, 0x00, 0x00, 0x00];
        assert_eq!(wasm_export_count(&m), Some(0));
    }

    /// One export entry: name length, name, kind, index.
    fn export_entry(name: &str, kind: u8, index: u8) -> Vec<u8> {
        let mut v = vec![name.len() as u8];
        v.extend_from_slice(name.as_bytes());
        v.push(kind);
        v.push(index);
        v
    }
    fn module_with_exports(entries: &[Vec<u8>]) -> Vec<u8> {
        let mut payload = vec![entries.len() as u8];
        for e in entries {
            payload.extend_from_slice(e);
        }
        let mut m = vec![0x00, b'a', b's', b'm', 0x01, 0x00, 0x00, 0x00];
        m.push(7);
        m.push(payload.len() as u8);
        m.extend_from_slice(&payload);
        m
    }

    #[test]
    fn exported_functions_are_counted() {
        let m = module_with_exports(&[export_entry("run", 0, 0), export_entry("step", 0, 1)]);
        assert_eq!(wasm_export_count(&m), Some(2));
    }

    /// THE CASE THAT MOTIVATED THE KIND FILTER. An export-less cdylib still exports `memory`,
    /// `__data_end` and `__heap_base` — the real 86-byte artifact reported 3 until this was fixed, which
    /// is precisely the false reassurance the export count exists to remove.
    #[test]
    fn memory_and_globals_do_not_count_as_callable_exports() {
        let m = module_with_exports(&[
            export_entry("memory", 2, 0),
            export_entry("__data_end", 3, 0),
            export_entry("__heap_base", 3, 1),
        ]);
        assert_eq!(wasm_export_count(&m), Some(0), "3 exports, 0 of them callable");
    }

    #[test]
    fn a_mixed_export_section_counts_only_the_functions() {
        let m = module_with_exports(&[
            export_entry("memory", 2, 0),
            export_entry("sort", 0, 0),
            export_entry("__heap_base", 3, 1),
        ]);
        assert_eq!(wasm_export_count(&m), Some(1));
    }

    /// A section BEFORE the export section must be skipped by its declared size, not scanned into.
    #[test]
    fn an_earlier_section_is_skipped_by_its_size() {
        let mut m = vec![0x00, b'a', b's', b'm', 0x01, 0x00, 0x00, 0x00];
        m.extend_from_slice(&[1, 3, 0xff, 0xff, 0xff]); // type section, 3 bytes of payload
        let entries = [export_entry("f", 0, 0)];
        let mut payload = vec![1u8];
        payload.extend_from_slice(&entries[0]);
        m.push(7);
        m.push(payload.len() as u8);
        m.extend_from_slice(&payload);
        assert_eq!(wasm_export_count(&m), Some(1));
    }

    #[test]
    fn a_truncated_section_header_does_not_panic() {
        let mut m = vec![0x00, b'a', b's', b'm', 0x01, 0x00, 0x00, 0x00];
        m.extend_from_slice(&[7]); // id with no size
        assert_eq!(wasm_export_count(&m), None);
    }

    #[test]
    fn a_size_running_past_the_end_does_not_panic() {
        let mut m = vec![0x00, b'a', b's', b'm', 0x01, 0x00, 0x00, 0x00];
        m.extend_from_slice(&[1, 0x7f]); // claims 127 bytes that are not there
        assert_eq!(wasm_export_count(&m), Some(0), "walks off the end and stops");
    }

    /// THERE ARE TWO WAYS INTO THE MATERIALIZER, and reading only one of them is a silent
    /// under-report: the records stay healthy, the exclusion stops covering them, and the sweep
    /// reports them broken. That is what happened when `crates/data` and `crates/bsc-config` adopted
    /// the alongside route — 20 records left Tier A and 16 came back FAILED.
    #[test]
    fn materializes_reads_both_opt_in_routes() {
        let shared = format!("[package]\nname = \"x\"\n{MATERIALIZE_MARKER}\n");
        let alongside = format!("[package]\nname = \"x\"\n\n[build-dependencies]\n{MATERIALIZE_DEP}\n");
        assert!(materializes(&shared), "the shared build script");
        assert!(materializes(&alongside), "the build-dependency the crate CALLS");
        assert!(!materializes("[package]\nname = \"x\"\n"), "and a crate that opted into neither");

        // THE SECTION IS PART OF THE QUESTION. `crates/bsc-graph` takes the same package as a
        // DEV-dependency, to drive the shipped symbols from `materialize_plan_tests`, and its source is
        // not materialized. Reading it as Tier A would EXCLUDE its records from the standalone sweep —
        // the quiet failure, since a record that is never swept never reports anything.
        let dev = format!("[package]\nname = \"x\"\n\n[dev-dependencies]\n{MATERIALIZE_DEP}\n");
        assert!(!materializes(&dev), "a dev-dependency is not an opt-in: {dev}");
        let plain = format!("[package]\nname = \"x\"\n\n[dependencies]\n{MATERIALIZE_DEP}\n");
        assert!(!materializes(&plain), "nor is a normal dependency: {plain}");
        // …and the section ENDS at the next table, rather than swallowing the rest of the file.
        let after = "[package]\nname = \"x\"\n\n[build-dependencies]\ntauri-build = \"2\"\n\n[dev-dependencies]\ngraph-materialize = { path = \"../graph-materialize\" }\n";
        assert!(!materializes(after), "{after}");

        // The PATH is not part of the question: `src-tauri` reaches the same package one level up.
        let up = "[package]\nname = \"x\"\n\n[build-dependencies]\ngraph-materialize = { path = \"../crates/graph-materialize\" }\n";
        assert!(materializes(up), "{up}");

        // …and each route reaches `is_tier_a` through the same set, so a record of either crate is
        // excluded from the standalone sweep.
        let crates = vec!["crates/bsc-blueprint".to_string(), "crates/data".to_string()];
        assert!(is_tier_a(Some("crates/data/src/schema.rs"), &crates));
        assert!(is_tier_a(Some("crates/bsc-blueprint/src/cli.rs"), &crates));
        assert!(!is_tier_a(Some("crates/bsc-graph/src/cli.rs"), &crates));
    }

    /// A CRATE OUTSIDE `crates/` IS STILL A CRATE, which is what the old `crates/` strip could not
    /// say. `src-tauri` is a workspace member one level up; keying on a bare name returned `None`
    /// for all 138 of its records and the sweep reported 119 healthy modules as broken.
    #[test]
    fn a_crate_outside_the_crates_directory_is_still_tier_a() {
        let crates = vec!["crates/bsc-blueprint".to_string(), "src-tauri".to_string()];
        assert_eq!(crate_of(Some("src-tauri/src/app/run.rs")), Some("src-tauri"));
        assert_eq!(crate_of(Some("crates/plandb/src/cli.rs")), Some("crates/plandb"));
        assert!(is_tier_a(Some("src-tauri/src/app/run.rs"), &crates));
        assert!(is_tier_a(Some("src-tauri/src/mobile/tunnel/transport.rs"), &crates));

        // The two namespaces cannot collide, which a bare name could not promise.
        let only_nested = vec!["crates/data".to_string()];
        assert!(is_tier_a(Some("crates/data/src/schema.rs"), &only_nested));
        assert!(!is_tier_a(Some("data/src/schema.rs"), &only_nested));

        // A record that names no crate module at all — a frontend `src/…` has no leading segment.
        assert_eq!(crate_of(Some("src/features/x.ts")), None);
        assert_eq!(crate_of(None), None);
    }

    /// The REAL manifests, so the constants above cannot drift into describing a shape the repo
    /// stopped using — and so that both routes stay represented rather than one being untested.
    /// Mirrors `finds both routes among the repo's own crates` in `scripts/graph-rust-compile.test.ts`;
    /// the two implementations must move together, which is exactly what this pair is for.
    #[test]
    fn both_routes_are_present_among_the_repos_own_crates() {
        let crates = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).parent().expect("crates/");
        let mut shared = 0usize;
        let mut alongside: Vec<String> = Vec::new();
        for entry in std::fs::read_dir(crates).expect("crates/ is readable").flatten() {
            let Ok(text) = std::fs::read_to_string(entry.path().join("Cargo.toml")) else { continue };
            if text.contains(MATERIALIZE_MARKER) {
                shared += 1;
            }
            if takes_materializer_as_a_build_dependency(&text) {
                alongside.push(entry.file_name().to_string_lossy().into_owned());
            }
        }
        // The one real crate holding the package in BOTH sections — the reason the dependency half is
        // section-scoped. It was the live "takes the materializer WITHOUT materializing" case until
        // `bsc-graph-compiles-from-the-graph` migrated this crate; it now materializes by the SHARED
        // route while still taking the package as a DEV-dependency, so what a real manifest proves here
        // is the sharper half: the two sections are read independently, and a dev-dependency is not the
        // build-dependency opt-in even in the one crate that carries both. The "and nothing else"
        // direction lives in `materializes_reads_both_opt_in_routes`, on a fixture.
        //
        // Named, so deleting the dev-dependency makes this test say the case is gone rather than
        // quietly stopping to cover it.
        let bsc_graph = std::fs::read_to_string(crates.join("bsc-graph").join("Cargo.toml")).expect("bsc-graph");
        assert!(
            bsc_graph.contains(MATERIALIZE_DEP),
            "bsc-graph takes graph-materialize (as a DEV-dependency) — the premise of this case"
        );
        assert!(
            !takes_materializer_as_a_build_dependency(&bsc_graph),
            "…and that DEV-dependency is NOT read as the build-dependency opt-in: {bsc_graph}"
        );
        assert!(
            bsc_graph.contains(MATERIALIZE_MARKER) && materializes(&bsc_graph),
            "…while the crate itself materializes by the SHARED route: {bsc_graph}"
        );
        assert!(shared > 20, "the shared route is the bulk of them, found {shared}");
        alongside.sort();
        assert_eq!(
            alongside,
            vec!["bsc-config".to_string(), "data".to_string()],
            "the alongside route's population, named so a third crate joining is a deliberate edit"
        );
    }
}
